import { describe, expect, it } from 'vitest';
import fixture from './fixtures/v03-f32-oracle.json';
import { createArithmeticContext, rational, toFloat32Bits } from '../src/trimline/numerics';

// Acceptance comparison of two already test-driven implementations. Expected values
// are generated by the independent Python Fraction/binary-search oracle, not JS floats.
describe('v03 exact Float32 comparison with independent Python oracle', () => {
  it('retains the complete generated fixture and canonical case identities', () => {
    expect(fixture.format).toBe('OrthoSculptFloat32Oracle');
    expect(fixture.version).toBe(1);
    expect(fixture.cases).toHaveLength(799);
    expect(new Set(fixture.cases.map(c => c.id)).size).toBe(fixture.cases.length);
    for (const c of fixture.cases) {
      expect(c.id).toMatch(/^[A-Za-z0-9][A-Za-z0-9_.-]*$/);
      expect(c.n).toMatch(/^(?:0|-?[1-9][0-9]*)$/);
      expect(c.d).toMatch(/^[1-9][0-9]*$/);
      expect(['finite', 'overflow']).toContain(c.expected.kind);
      if (c.expected.kind === 'finite') {
        expect(typeof c.expected.bits).toBe('number');
        expect(Number.isInteger(c.expected.bits)).toBe(true);
        expect(c.expected.bits).toBeGreaterThanOrEqual(0);
        expect(c.expected.bits).toBeLessThanOrEqual(0xffffffff);
      } else {
        expect(Object.hasOwn(c.expected, 'bits')).toBe(false);
      }
    }
  });

  it.each(fixture.cases)('matches independently generated $id', c => {
    const ctx = createArithmeticContext({ maxBits: 4096, maxOperations: 10000 });
    const value = rational(BigInt(c.n), BigInt(c.d), ctx);
    if (c.expected.kind === 'overflow') {
      expect(() => toFloat32Bits(value, ctx)).toThrowError(
        expect.objectContaining({ name: 'NumericsError', code: 'FLOAT32_OVERFLOW' }),
      );
    } else {
      expect(c.expected.kind).toBe('finite');
      expect(toFloat32Bits(value, ctx)).toBe(c.expected.bits);
    }
  });

  it('detects a deliberately flipped expected bit without modifying the fixture', () => {
    const c = fixture.cases.find(c => c.id === 'double-round-positive');
    if (!c || c.expected.kind !== 'finite' || c.expected.bits === undefined) {
      throw new Error('Missing finite double-rounding reference case');
    }
    const ctx = createArithmeticContext({ maxBits: 4096, maxOperations: 10000 });
    const actual = toFloat32Bits(rational(BigInt(c.n), BigInt(c.d), ctx), ctx);
    const deliberatelyWrong = (c.expected.bits ^ 1) >>> 0;
    expect(actual).toBe(c.expected.bits);
    expect(actual).not.toBe(deliberatelyWrong);
  });
});
